def predict(tokens, prompt):
    seq = tokens[1:]                      # drop BOS
    n_fo = seq.count(2)                   # head 1.1 (E0009)
    n_ni = seq.count(4)                   # head 1.2 (E0010)
    if n_fo > n_ni: return 7              # J   (mlp1 -> mlp2, E0011)
    if n_fo < n_ni: return 8              # V
    return 9                              # Y   (V0001: 200/200)
